    prompt_ids, answer_ids = vocab.encode(prompt), vocab.encode(target)
    ids = prompt_ids + answer_ids + [0]
    if len(ids) > max_tokens:
        raise ValueError(f"sequence has {len(ids)} tokens, limit {max_tokens}; never truncate")
