n=int(input()); s=input().strip()
def possible(k):
    first={}
    for i in range(n-k+1):
        part=s[i:i+k]
        if part in first:
            if i-first[part]>=k: return True
        else: first[part]=i
    return False
lo,hi=0,n//2+1
while hi-lo>1:
    mid=(lo+hi)//2
    if possible(mid): lo=mid
    else: hi=mid
print(lo)

