from functools import lru_cache
x,y=map(int,input().split())
@lru_cache(None)
def solve(v):
    if v<=x: return x-v
    ans=v-x
    if v%2==0: return min(ans,1+solve(v//2))
    return min(ans,2+solve(v//2),2+solve(v//2+1))
print(solve(y))

